queries.q2:
// Q2: shortest dependency chain from a direct dependency to the affected locked package.
// shortestPath is only valid in WITH/RETURN on this engine; *0..8 lets a direct dependency return length 0.
// Params: $artifact (Artifact.id), $purl (PackageVersion.purl)
MATCH (a:Artifact {id: $artifact})-[:LOCKS]->(bad:LockedDep)-[:IS]->(:PackageVersion {purl: $purl}),
      (a)-[:LOCKS]->(top:LockedDep {direct: true})
WITH top, bad, shortestPath((top)-[:REQUIRES*0..8]->(bad)) AS p
WHERE p IS NOT NULL
RETURN [n IN nodes(p) | n.name + '@' + n.version] AS chain, length(p) AS hops, [n IN nodes(p) | n.key] AS keys
ORDER BY hops
LIMIT 1

queries.q5:
// Q5: which accepted decisions rest on an assumption that has since been superseded?
// Truth maintenance in one query: a fact is superseded when a later event contradicts it.
// Params: $at_ms
MATCH (d:Decision {status: 'accepted'})-[:ASSUMES]->(f:Fact)
WHERE f.superseded_ms IS NOT NULL AND f.superseded_ms <= $at_ms
MATCH (d)-[:ABOUT]->(adv:Advisory), (d)-[:FOR]->(a:Artifact)
RETURN d.id AS decision, d.verdict AS verdict, adv.id AS advisory, a.id AS artifact,
       collect(f.id) AS broken, max(f.superseded_ms) AS broken_ms
ORDER BY decision
